using namespace std;

class Solution {
    int memo[25][7][7][243];
    int p3[6];
    int M, N, total;

    int solve(int pos, int ic, int ec, int mask) {
        if (pos == total || (ic == 0 && ec == 0)) return 0;
        if (memo[pos][ic][ec][mask] != -1) return memo[pos][ic][ec][mask];

        int r = pos / N, c = pos % N;
        int up = mask / p3[N - 1];
        int left = c > 0 ? (mask % 3) : 0;
        int next_mask_base = (mask % p3[N - 1]) * 3;

        // 1. Leave empty
        int ans = solve(pos + 1, ic, ec, next_mask_base);

        // 2. Introvert
        if (ic > 0) {
            int cost = 120;
            if (up == 1) cost -= 60;
            else if (up == 2) cost -= 10;
            if (left == 1) cost -= 60;
            else if (left == 2) cost -= 10;
            ans = max(ans, cost + solve(pos + 1, ic - 1, ec, next_mask_base + 1));
        }

        // 3. Extrovert
        if (ec > 0) {
            int cost = 40;
            if (up == 1) cost -= 10;
            else if (up == 2) cost += 40;
            if (left == 1) cost -= 10;
            else if (left == 2) cost += 40;
            ans = max(ans, cost + solve(pos + 1, ic, ec - 1, next_mask_base + 2));
        }

        return memo[pos][ic][ec][mask] = ans;
    }

public:
    int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        if (m < n) swap(m, n);
        M = m; N = n; total = m * n;
        p3[0] = 1;
        for (int i = 1; i <= 5; ++i) p3[i] = p3[i - 1] * 3;
        memset(memo, -1, sizeof(memo));
        return solve(0, introvertsCount, extrovertsCount, 0);
    }
};

class Solution {
    private int[][][][] memo;
    private int[] p3 = new int[6];
    private int M, N, total;

    private int solve(int pos, int ic, int ec, int mask) {
        if (pos == total || (ic == 0 && ec == 0)) return 0;
        if (memo[pos][ic][ec][mask] != -1) return memo[pos][ic][ec][mask];

        int c = pos % N;
        int up = mask / p3[N - 1];
        int left = c > 0 ? (mask % 3) : 0;
        int nextMaskBase = (mask % p3[N - 1]) * 3;

        int ans = solve(pos + 1, ic, ec, nextMaskBase);

        if (ic > 0) {
            int cost = 120;
            if (up == 1) cost -= 60;
            else if (up == 2) cost -= 10;
            if (left == 1) cost -= 60;
            else if (left == 2) cost -= 10;
            ans = Math.max(ans, cost + solve(pos + 1, ic - 1, ec, nextMaskBase + 1));
        }

        if (ec > 0) {
            int cost = 40;
            if (up == 1) cost -= 10;
            else if (up == 2) cost += 40;
            if (left == 1) cost -= 10;
            else if (left == 2) cost += 40;
            ans = Math.max(ans, cost + solve(pos + 1, ic, ec - 1, nextMaskBase + 2));
        }

        return memo[pos][ic][ec][mask] = ans;
    }

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        if (m < n) {
            int tmp = m; m = n; n = tmp;
        }
        M = m; N = n; total = m * n;
        p3[0] = 1;
        for (int i = 1; i <= 5; ++i) p3[i] = p3[i - 1] * 3;
        memo = new int[25][7][7][243];
        for (int i = 0; i < 25; ++i) {
            for (int j = 0; j < 7; ++j) {
                for (int k = 0; k < 7; ++k) {
                    java.util.Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
        return solve(0, introvertsCount, extrovertsCount, 0);
    }
}

/**
 * @param {number} m
 * @param {number} n
 * @param {number} introvertsCount
 * @param {number} extrovertsCount
 * @return {number}
 */
var getMaxGridHappiness = function(m, n, introvertsCount, extrovertsCount) {
    if (m < n) {
        const tmp = m; m = n; n = tmp;
    }
    const total = m * n;
    const p3 = [1, 3, 9, 27, 81, 243];
    const memo = new Map();

    function solve(pos, ic, ec, mask) {
        if (pos === total || (ic === 0 && ec === 0)) return 0;
        const key = (pos << 16) | (ic << 12) | (ec << 8) | mask;
        if (memo.has(key)) return memo.get(key);

        const c = pos % n;
        const up = Math.floor(mask / p3[n - 1]);
        const left = c > 0 ? (mask % 3) : 0;
        const nextMaskBase = (mask % p3[n - 1]) * 3;

        let ans = solve(pos + 1, ic, ec, nextMaskBase);

        if (ic > 0) {
            let cost = 120;
            if (up === 1) cost -= 60;
            else if (up === 2) cost -= 10;
            if (left === 1) cost -= 60;
            else if (left === 2) cost -= 10;
            ans = Math.max(ans, cost + solve(pos + 1, ic - 1, ec, nextMaskBase + 1));
        }

        if (ec > 0) {
            let cost = 40;
            if (up === 1) cost -= 10;
            else if (up === 2) cost += 40;
            if (left === 1) cost -= 10;
            else if (left === 2) cost += 40;
            ans = Math.max(ans, cost + solve(pos + 1, ic, ec - 1, nextMaskBase + 2));
        }

        memo.set(key, ans);
        return ans;
    }

    return solve(0, introvertsCount, extrovertsCount, 0);
};
